visual.code:
ul {
  list-style-type: none;
  margin: 0;
  padding: 0;
  width: 200px;
  background-color: #f1f1f1;
}

li a {
  display: block;
  color: black;
  padding: 8px 16px;
  text-decoration: none;
}
li a:hover {
  background-color: #555555;
  color: white;
}

ul {
  border: 1px solid #555555;
}
li {
  text-align: center;
  border-bottom: 1px solid #555555;
}
li:last-child {
  border-bottom: none;
}

ul {
  height: 100%;
  position: fixed;
  overflow: auto;
}
